#[allow(dead_code, unused_variables)]
pub fn calculate_assiette_csg_plus_values(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {

    // Plus-values mobilières brutes (avant abattement)
    let f3vg = calculate_f3vg(parameters, period, profile);
    let f3we = calculate_f3we(parameters, period, profile);
    let f3ua = calculate_f3ua(parameters, period, profile);
    let f3sj = calculate_f3sj(parameters, period, profile);
    let f3tj = calculate_f3tj(parameters, period, profile);
    let f3sk = calculate_f3sk(parameters, period, profile);
    let f3vt = calculate_f3vt(parameters, period, profile);
    let f3wi = calculate_f3wi(parameters, period, profile);
    let f3wj = calculate_f3wj(parameters, period, profile);
    let rpns_pvce_i = calculate_rpns_pvce(parameters, period, profile);
    let f3pi = calculate_f3pi(parameters, period, profile);
    let f3an = calculate_f3an(parameters, period, profile);

    let rpns_pvce = rpns_pvce_i;

    let glo_taxation_ir_forfaitaire = calculate_glo_taxation_ir_forfaitaire(parameters, period, profile);

    // Plus-values immobilières
    let f3vz = calculate_f3vz(parameters, period, profile);

    // plus-values vente d'entreprise retraite
    let pveximpres_i = calculate_pveximpres(parameters, period, profile);
    let pveximpres = pveximpres_i;

    return f3vg + f3ua + f3vz + f3we + rpns_pvce + f3sj + f3sk + f3vt + f3wi + f3wj + f3pi + f3tj + f3an + glo_taxation_ir_forfaitaire + pveximpres;
    0.0_f64
}

