#[allow(dead_code, unused_variables)]
pub fn calculate_credit_cotisations_syndicales(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    // UNTRANSLATED: Cotisations syndicales : réduction d'impôt (2002-2011) puis crédit d'impôt (2012- )
    let f7ac = calculate_f7ac(parameters, period, profile);

    let cotisations_versees = f7ac;

    let salaire_imposable = calculate_salaire_imposable(parameters, period, profile);
    let chomage_imposable = calculate_chomage_imposable(parameters, period, profile);
    let retraite_imposable = calculate_retraite_imposable(parameters, period, profile);

    let cotisations_syndicales = parameters.get_scalar("impot_revenu/credits_impots/cotisations_syndicales").unwrap_or(0.0);

    let plafond = (salaire_imposable + chomage_imposable + retraite_imposable) * cotisations_syndicales.plafond;

    return (cotisations_syndicales.taux * (cotisations_versees.min(plafond)));
    0.0_f64
}

