#[allow(dead_code, unused_variables)]
pub fn calculate_crds_rsa_activite(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let rsa_activite = calculate_rsa_activite(parameters, period, profile);
    let taux_crds = parameters.get_scalar("prelevements_sociaux/contributions_sociales/crds").unwrap_or(0.0);

    return - taux_crds * rsa_activite;
}

#[allow(dead_code, unused_variables)]
pub fn calculate_reduction_cotisations_syndicales(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    // UNTRANSLATED: Cotisations syndicales : réduction d'impôt (2002-2011) puis crédit d'impôt (2012- )
    // UNTRANSLATED: NB: This is but an approximation of the true calculation, as it is done on the level of the tax unit.
    // UNTRANSLATED: In reality, the ceilings of 1 % of revenues are applied on the individual level (cf. BOI-IR-RICI-20).

    let f7ac = calculate_f7ac(parameters, period, profile);

    let cotisations_versees = f7ac;

    let salaire_imposable = calculate_salaire_imposable(parameters, period, profile);
    let chomage_imposable = calculate_chomage_imposable(parameters, period, profile);
    let retraite_imposable = calculate_retraite_imposable(parameters, period, profile);

    let cotisations_syndicales = parameters.get_scalar("impot_revenu/calcul_reductions_impots/cotisations_syndicales").unwrap_or(0.0);

    let plafond = (salaire_imposable + chomage_imposable + retraite_imposable) * cotisations_syndicales.plafond;

    return (cotisations_syndicales.taux * (cotisations_versees.min(plafond)));
    0.0_f64
}

#[allow(dead_code, unused_variables)]
pub fn calculate_exoneration_cotisations_employeur_professionnalisation(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let age = calculate_age(parameters, period, profile);
    let mmid_employeur = calculate_mmid_employeur_net_allegement(parameters, period, profile);
    let famille = calculate_famille_net_allegement(parameters, period, profile);
    let vieillesse_plafonnee_employeur = calculate_vieillesse_plafonnee_employeur(parameters, period, profile);
    // FIXME: correspond bien à vieillesse de base ?
    let cotisations_exonerees = mmid_employeur + famille + vieillesse_plafonnee_employeur;

    return cotisations_exonerees * (age > 45);
    // FIXME: On est bien d'accord qu'il y a les exos uniquement pour les
    // plus de 45 ans?
    0.0_f64
}
